head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30408";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — reservChkList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30408.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_tm", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '09'); } }, { id: "if_tm_2", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '10'); } }, { id: "if_tm_3", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '11'); } }, { id: "if_tm_4", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '12'); } }, { id: "if_tm_5", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '13'); } }, { id: "if_tm_6", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '14'); } }, { id: "if_tm_7", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '15'); } }, { id: "if_tm_8", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '16'); } }, { id: "if_tm_9", fn: function(){ return ((dlt_reservChkList.getCellData(0, "tm") ?? (() => { throw new Error("unresolved:" + "entity.tm"); })()) === '17'); } }, { id: "if_reservChkList", fn: function(){ return (!(String(((dma_pageContext.get("reservChkList") ?? "")) == null ? '' : ((dma_pageContext.get("reservChkList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — jldfil30408: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
